head.script:
// 테스트 설명, 유효성 값 설정
//  - "다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (column 샘플 관례, 설정 영역 con 옵션 미생성)
//  - 본 샘플(_1) : CustomFilter 필터 기준 (GridView useFilterList 미설정, 정적 아이템)
//    FilterList 필터(useFilterList=true) 의 BindItemset 조건은 column_P_filterDisplayMode_2 소유
scwin.tData = {
    "description" : "[column > P > filterDisplayMode]<br/>Header Column 의 필터 기능(CustomFilter, FilterList)에서 필터 항목이 표시되는 형식을 설정합니다.",
    "validation" : [
        "Column 의 inputType='select','checkcombobox','autoComplete' 인 경우에 정상 동작합니다.",
        "Body Column 에 설정하면 해당 Column 의 Header Column 이 useFilter='true' 인 경우에 동작합니다.",
        "'label' 설정 시, 필터 항목에 아이템의 Label 값을 표시합니다.",
        "미설정 시, 필터 항목에 아이템의 Label 값을 표시합니다.",
        "'value' 설정 시, 필터 항목에 아이템의 Value 값을 표시합니다.",
        "'label delim value' 설정 시, 필터 항목에 아이템의 Label 값과 Value 값을 구분자로 구분하여 순서대로 표시합니다.",
        "'value delim label' 설정 시, 필터 항목에 아이템의 Value 값과 Label 값을 구분자로 구분하여 순서대로 표시합니다.",
        "필터 항목에서 구분자는 Column 의 delimiter 속성값이 적용됩니다.",
        "Column 의 inputType 속성값이 'select','checkcombobox','autoComplete' 가 아니면 CustomFilter 필터에 동일값이 두번 표시됩니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (gdl_boolean : 1=미설정 / 2=true / 3=false)
    con_inputType.setValue("select");
    con_filterDisplayMode.setValue("value delim label");
    con_useFilter.setValue("2");
    con_delimiter.setValue(":");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 아이템 : 서울(SEL) / 부산(BSN) / 대구(DGU) / 인천(ICN)
//  - city Column 데이터는 SEL / BSN / ICN 이므로 필터 항목은 데이터에 있는 3개 값만 표시됨
scwin.itemList = [
    { "label" : "서울", "value" : "SEL" },
    { "label" : "부산", "value" : "BSN" },
    { "label" : "대구", "value" : "DGU" },
    { "label" : "인천", "value" : "ICN" }
];



// comp 생성
//  - branch : 비교용 text Column
//  - city   : 검증 대상 Body Column (inputType / filterDisplayMode / delimiter = con 값)
//             Header Column(column2) 의 useFilter = con 값
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cInputType = con_inputType.getValue();
    let cFilterDisplayMode = con_filterDisplayMode.getValue();
    let cUseFilter = con_useFilter.getText();
    let cDelimiter = con_delimiter.getValue();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] city Column 아이템 : 서울(SEL) / 부산(BSN) / 대구(DGU) / 인천(ICN), 데이터 : SEL / BSN / ICN\n[절차] city Header 필터 버튼 클릭 -> 필터 창 첫번째 값 입력란 목록 열기 -> 필터 창 닫기 -> 필터 항목 확인"', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // 바인딩 dataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="branch" name="branch" dataType="text"></w2:column>';
    strDlt += '<w2:column id="city" name="city" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "branch" : "본사", "city" : "SEL" },
        { "branch" : "영남지사", "city" : "BSN" },
        { "branch" : "수도권지사", "city" : "ICN" }
    ], false);

    // Header Column 속성
    let attrUseFilter = (cUseFilter === '') ? '' : ' useFilter="' + cUseFilter + '"';

    // city Column 속성
    let attrCity = ' inputType="' + cInputType + '"';
    attrCity += (cFilterDisplayMode === '') ? '' : ' filterDisplayMode="' + cFilterDisplayMode + '"';
    attrCity += (cDelimiter === '') ? '' : ' delimiter="' + cDelimiter + '"';

    // 정적 아이템 (inputType='text' 는 아이템 없음)
    let strItems = '';
    if (cInputType !== "text") {
        strItems += '<w2:choices>';
        scwin.itemList.forEach(function (item) {
            strItems += '<w2:item><w2:label>' + item.label + '</w2:label><w2:value>' + item.value + '</w2:value></w2:item>';
        });
        strItems += '</w2:choices>';
    }

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:500px;height:150px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="column1" value="branch"></w2:column>';
    strTarget += '<w2:column width="330" style="" inputType="text" id="column2" value="city (' + cInputType + ')"' + attrUseFilter + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="branch" value="" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="330" style="text-align:left;" id="city" value=""' + attrCity + '>' + strItems + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 따옴표로 감싸 공백·구분자 확인
scwin.quote = function (str) {
    return "'" + String(str) + "'";
}



// validation 1 ~ 9 : CustomFilter 필터 항목 텍스트
//  - 필터 버튼이 없으면(useFilter) 필터 버튼 없음
//  - CustomFilter : 필터 창 첫번째 값 입력란의 아이템 리스트 항목 (한번 열었던 리스트는 필터 창을 닫아도 DOM 이 유지되고, Target 재생성 시 삭제됨)
scwin.btn_checkFilterItem_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    if (!document.querySelector("[id='" + target1.id + "_column2_filter']")) {
        bottom.setReturnValue("필터 버튼 없음");
        return;
    }
    let arr = [];
    document.querySelectorAll("td[id^='" + target1.id + "_item_0_autocomplete_'][id*='_itemTable_']").forEach(function (td) {
        if (/_itemTable_\d+$/.test(td.id)) {
            arr.push(scwin.quote(td.textContent));
        }
    });
    bottom.setReturnValue("CustomFilter 항목 : " + (arr.length ? arr.join(" / ") : "열린 필터 항목 리스트 없음"));
}
